import{_ as a,o,c as e,a0 as n}from"./chunks/framework.DqMqoJl9.js";const l="data:image/png;base64,",A=JSON.parse('{"title":"坐标定位","description":"","frontmatter":{},"headers":[],"relativePath":"svg/3-positions.md","filePath":"svg/3-positions.md","lastUpdated":1791426062000}'),p={name:"svg/3-positions.md"};function t(c,s,r,d,i,y){return o(),e("div",null,[...s[0]||(s[0]=[n('<h1 id="坐标定位" tabindex="-1">坐标定位 <a class="header-anchor" href="#坐标定位" aria-label="Permalink to &quot;坐标定位&quot;">​</a></h1><h2 id="_1-网格" tabindex="-1">1 网格 <a class="header-anchor" href="#_1-网格" aria-label="Permalink to &quot;1 网格&quot;">​</a></h2><p>对于所有元素，SVG 使用的坐标系统或者说网格系统，和 Canvas 用的差不多（所有计算机绘图都差不多）</p><p>这种坐标系统是：以页面的左上角为 <code>(0,0)</code> 坐标点，坐标以像素为单位，x 轴正方向是向右，y 轴正方向是向下</p><p><img src="'+l+'" alt=""></p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">rect</span><span style="color:#6F42C1;"> x</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;0&quot;</span><span style="color:#6F42C1;"> y</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;0&quot;</span><span style="color:#6F42C1;"> width</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;100&quot;</span><span style="color:#6F42C1;"> height</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;100&quot;</span><span style="color:#24292E;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>定义一个矩形，即从左上角开始，向右延展 <code>100px</code>，向下延展 <code>100px</code>，形成一个 <code>100*100</code> 大的矩形。</p><h2 id="_2-什么是像素" tabindex="-1">2 什么是像素 <a class="header-anchor" href="#_2-什么是像素" aria-label="Permalink to &quot;2 什么是像素&quot;">​</a></h2><p>基本上，在 SVG 文档中的 1 个像素对应输出设备（比如显示屏）上的 1 个像素</p><p>但是这种情况是可以改变的，否则 SVG 的名字里也不至于会有“Scalable”（可缩放）这个词。如同 CSS 可以定义字体的绝对大小和相对大小，SVG 也可以定义绝对大小（比如使用“pt”或“cm”标识维度）同时 SVG 也能使用相对大小，只需给出数字，不标明单位，输出时就会采用用户的单位</p><p>在没有进一步规范说明的情况下，1 个用户单位等同于 1 个屏幕单位</p><p>要明确改变这种设定，SVG 里有多种方法。我们从 svg 根元素开始：</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">svg</span><span style="color:#6F42C1;"> width</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;100&quot;</span><span style="color:#6F42C1;"> height</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;100&quot;</span><span style="color:#24292E;">&gt;…&lt;/</span><span style="color:#22863A;">svg</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>上面的元素定义了一个 <code>100*100px</code> 的 SVG 画布，这里 1 用户单位等同于 1 屏幕单位</p><div class="language-xml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">svg</span><span style="color:#6F42C1;"> width</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;200&quot;</span><span style="color:#6F42C1;"> height</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;200&quot;</span><span style="color:#6F42C1;"> viewBox</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;0 0 100 100&quot;</span><span style="color:#24292E;">&gt;…&lt;/</span><span style="color:#22863A;">svg</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这里定义的画布尺寸是 <code>200*200px</code>。但是，viewBox 属性定义了画布上可以显示的区域：从 <code>(0,0)</code> 点开始，100 宽*100 高的区域。这个 <code>100*100</code> 的区域，会放到 <code>200*200</code> 的画布上显示。于是就形成了放大两倍的效果</p><p>用户单位和屏幕单位的映射关系被称为用户坐标系统。除了缩放之外，坐标系统还可以旋转、倾斜、翻转。默认的用户坐标系统 1 用户像素等于设备上的 1 像素（但是设备上可能会自己定义 1 像素到底是多大）。在定义了具体尺寸单位的 SVG 中，比如单位是 <code>cm</code> 或 <code>in</code>，最终图形会以实际大小的 1 比 1 比例呈现</p>',17)])])}const g=a(p,[["render",t]]);export{A as __pageData,g as default};
